          "code": "struct Good {\n    int low_;\n    int high_;\n    Good() : low_(10), high_(low_ + 5) {}\n};\n\nstruct Broken {\n    int high_;\n    int low_;\n    Broken() : low_(10), high_(low_ + 5) {}\n};\n\n// Внутри main:\n// Good a;    // low_ == 10, high_ == 15\n// Broken b;  // неопределённое поведение при создании b"
