          "html": "У <code>Good</code> сначала инициализируется <code>low_</code> числом 10. Когда начинается <code>high_(low_ + 5)</code>, читать <code>low_</code> уже можно. Верхняя граница получается равной 15. В <code>Broken</code> список внешне похож, но первым объявлено <code>high_</code>. Для вычисления его значения требуется прочитать <code>low_</code>, которому этот конструктор ещё не задал число."
