          "type": "text",
          "html": "У поля может быть и начальное значение прямо в объявлении: например, <code>int low_ = 10;</code>. Такой <strong>инициализатор поля по умолчанию</strong> используется, если конструктор не задаёт для этого поля свой. Если же есть <code>: low_(25)</code>, используется 25, а выражение после <code>=</code> в объявлении вообще не вычисляется. Это выбор одного способа инициализации, а не сначала запись 10, потом запись 25."
