          "html": "Почему не предложить два независимых метода <code>set_low</code> и <code>set_high</code>? Их тоже можно снабдить проверками, но тогда пользователю придётся выбирать допустимый промежуточный диапазон. Для перехода из [10, 20] в [30, 40] вызов <code>set_low(30)</code> сначала недопустим; пришлось бы начинать с верхней границы. Метод <code>set_bounds</code> выражает задачу целиком: «заменить обе границы, если новая пара подходит». Это решение о смысле интерфейса, не требование синтаксиса C++."
