          "answer": "Первый вызов возвращает <code>false</code> и сохраняет [10, 20]: проверка завершает метод до любого присваивания. Второй возвращает <code>true</code> и оставляет [30, 40]. При отказе сохраняется не только условие <code>low_ &lt;= high_</code>, но и прежние значения: метод не заменяет их какой-нибудь другой допустимой парой."
