          "type": "code",
          "caption": "Первая часть программы: доступные способы создания Interval",
          "code": "#include <stdexcept>\n\nclass Interval {\n    int low_;\n    int high_;\npublic:\n    Interval() = delete;\n    Interval(int low, int high) : low_(low), high_(high) {\n        if (low > high)\n            throw std::invalid_argument(\"reversed interval\");\n    }\n\n    static Interval point(int value) {\n        return Interval{value, value};\n    }\n\n    int low() const { return low_; }\n    int high() const { return high_; }\n};\n\n// Interval empty;               // ошибка: конструктор удалён\n// Interval normal{10, 20};       // обычный диапазон\n// auto single = Interval::point(7); // диапазон [7, 7]"
