          "html": "При <code>Interval::point(7)</code> параметр <code>value</code> получает 7. Выражение <code>Interval{value, value}</code> использует знакомый конструктор с двумя числами, то есть создаёт результат с границами 7 и 7. Проверка проходит: равные границы разрешены. <code>return</code> возвращает это значение вызывающему коду, который инициализирует им <code>single</code>. Поэтому вторая строка вывода — <code>7 7</code>. Вызова <code>new</code> и возвращаемого указателя в этом решении нет."
