          "answer": "Пропадёт сообщение <code>-pair</code>, но поля не останутся неразрушенными. Автоматически предоставленный деструктор Pair вызовет деструктор second, затем first. При создании по-прежнему сначала возникнут first и second, затем выполнится тело Pair()."
