          "type": "text",
          "html": "У счётчика есть важная граница. Строка <code>Ticket copy = first;</code> создала бы новый объект через автоматически предоставленный конструктор копирования, а не повторным вызовом <code>Ticket()</code>. Тело с <code>++issued_</code> при этом не выполнилось бы; static-поле не копируется как часть билета. Если нужно считать все живые объекты, придётся согласовать каждый способ создания, включая копирование, с разрушением. Например, увеличение только в обычном конструкторе и уменьшение в деструкторе даст неверный результат, если копии разрешены."
