          "answer": "<code>Request::State</code> — тип, saved — новая переменная этого типа, <code>request.state()</code> — вызов читающего метода конкретного request. Его поле state_ хранит состояние. Типу State слово static не нужно: объявление типа само по себе не является отдельным полем каждого объекта и не хранит общее состояние."
