          "answer": "При <code>Clock b = a;</code> создаются отдельные часы с тем же начальным временем <code>5:59:59</code>. Вызов <code>b.tick()</code> выполняет переносы и меняет только <code>b</code> на <code>6:0:0</code>. В <code>a.try_set(6, 0, 60)</code> секунда 60 недопустима: результат <code>false</code>, все прежние поля <code>a</code> сохраняются, поэтому <code>a</code> остаётся в <code>5:59:59</code>. Если объявить <code>Clock&amp; b = a;</code>, имя <code>b</code> станет ссылкой на тот же объект: <code>b.tick()</code> изменит и наблюдаемое через <code>a</code> время на <code>6:0:0</code>. Последующий отказ сохранит уже это время. Разница возникает при объявлении копии или ссылки, а не в алгоритме <code>tick</code>."
