          "html": "<strong>Перед тестами объясни решение своими словами.</strong> Почему выбранные поля достаточны? Какие значения допустимы? Что происходит до первой записи в <code>try_set</code>? На каком <code>return</code> заканчивается каждый случай <code>tick</code>? Почему копия независима, а ссылка нет? Такой порядок связывает условие, код и наблюдаемый результат. Для этой задачи не потребовались наследование, <code>new</code>, собственный деструктор или исключения: полнота решения определяется выполнением договора, а не набором возможностей C++."
